public interface IReader { string Read(); }
public interface IWriter { void Write(string text); }
public sealed class MemoryStore : IReader, IWriter
{
    private string value = "";
    string IReader.Read() => value;
    void IWriter.Write(string text) => value = text;
}
public static class Reports
{
    public static string ReadReport(IReader source) => source.Read();
    public static string Example()
    {
        var store = new MemoryStore();
        ((IWriter)store).Write("report");
        return ReadReport((IReader)store);
    }
}
